files.patch:
@@ -58,6 +58,7 @@ static int meminfo_proc_show(struct seq_file *m, void *v)
 		unsigned long memsw_usage = 0;
 		unsigned long memusage = page_counter_read(&memcg->memory);
 		unsigned long proactive_swap;
+		unsigned long normal_swap_usage = 0;

 		for (lru = LRU_BASE; lru < NR_LRU_LISTS; lru++)
 			pages[lru] = memcg_page_state(memcg, NR_LRU_BASE + lru);
@@ -86,27 +87,36 @@ static int meminfo_proc_show(struct seq_file *m, void *v)
 				i.totalswap = 0;
 				i.freeswap = 0;
 			} else if (memsw == PAGE_COUNTER_MAX) {
-				i.freeswap = i.totalswap - memsw_usage;
+				normal_swap_usage = (memsw_usage > proactive_swap) ?
+					(memsw_usage - proactive_swap) : 0;
+				i.freeswap = (i.totalswap > normal_swap_usage) ?
+					(i.totalswap - normal_swap_usage) : 0;
 			} else {
-				i.freeswap = i.totalswap - (memsw_usage - memusage);
 				i.totalswap = memsw - totalram;
+				normal_swap_usage = (memsw_usage > memusage + proactive_swap) ?
+					(memsw_usage - memusage - proactive_swap) : 0;
+				i.freeswap = (i.totalswap > normal_swap_usage) ?
+					(i.totalswap - normal_swap_usage) : 0;
 			}
 		} else { // v2
 			if (!memsw) {
 				i.totalswap = 0;
 				i.freeswap = 0;
 			} else if (memsw == PAGE_COUNTER_MAX) {
-				i.freeswap = i.totalswap - memsw_usage;
+				normal_swap_usage = (memsw_usage > proactive_swap) ?
+					(memsw_usage - proactive_swap) : 0;
+				i.freeswap = (i.totalswap > normal_swap_usage) ?
+					(i.totalswap - normal_swap_usage) : 0;
 			} else {
 				i.totalswap = memsw;
-				i.freeswap = i.totalswap - memsw_usage;
+				normal_swap_usage = (memsw_usage > proactive_swap) ?
+					(memsw_usage - proactive_swap) : 0;
+				i.freeswap = (i.totalswap > normal_swap_usage) ?
+					(i.totalswap - normal_swap_usage) : 0;
 			}
 		}

-		if (!i.totalswap && proactive_swap) {
-			i.totalswap = proactive_swap;
-			i.freeswap = 0;
-		}
+		i.totalswap += proactive_swap;

 		available = i.freeram + sreclaimable + cached_inactive;
 		committed = 0;

@@ -2873,6 +2873,7 @@ static int do_sysinfo(struct sysinfo *info)
 		unsigned long memusage = page_counter_read(&memcg->memory);
 		unsigned long totalram = (u64)READ_ONCE(memcg->memory.max);
 		unsigned long proactive_swap;
+		unsigned long normal_swap_usage = 0;

 		memsw = READ_ONCE(memcg->memsw.max);
 		memsw_usage = page_counter_read(&memcg->memsw);
@@ -2882,25 +2883,40 @@ static int do_sysinfo(struct sysinfo *info)
 		info->freeram = info->freehigh = totalram - memusage;
 		if (!cgroup_subsys_on_dfl(memory_cgrp_subsys)) { // if cgroup v1 (see do_memsw_account in mm/memcontrol.h)
 			if (!memsw || (memsw == totalram) || (memsw == PAGE_COUNTER_MAX)) {
-				info->totalswap = 0;
-				info->freeswap = 0;
+				if (memsw == PAGE_COUNTER_MAX) {
+					normal_swap_usage = (memsw_usage > proactive_swap) ?
+						(memsw_usage - proactive_swap) : 0;
+					info->freeswap = (info->totalswap > normal_swap_usage) ?
+						(info->totalswap - normal_swap_usage) : 0;
+				} else {
+					info->totalswap = 0;
+					info->freeswap = 0;
+				}
 			} else {
 				info->totalswap = memsw - totalram;
-				info->freeswap = info->totalswap - (memsw_usage - memusage);
+				normal_swap_usage = (memsw_usage > memusage + proactive_swap) ?
+					(memsw_usage - memusage - proactive_swap) : 0;
+				info->freeswap = (info->totalswap > normal_swap_usage) ?
+					(info->totalswap - normal_swap_usage) : 0;
 			}
 		} else { // v2
 			if (!memsw) {
 				info->totalswap = 0;
 				info->freeswap = 0;
+			} else if (memsw == PAGE_COUNTER_MAX) {
+				normal_swap_usage = (memsw_usage > proactive_swap) ?
+					(memsw_usage - proactive_swap) : 0;
+				info->freeswap = (info->totalswap > normal_swap_usage) ?
+					(info->totalswap - normal_swap_usage) : 0;
 			} else {
 				info->totalswap = memsw;
-				info->freeswap = info->totalswap - memsw_usage;
+				normal_swap_usage = (memsw_usage > proactive_swap) ?
+					(memsw_usage - proactive_swap) : 0;
+				info->freeswap = (info->totalswap > normal_swap_usage) ?
+					(info->totalswap - normal_swap_usage) : 0;
 			}
 		}
-		if (!info->totalswap && proactive_swap) {
-			info->totalswap = proactive_swap;
-			info->freeswap = 0;
-		}
+		info->totalswap += proactive_swap;
 		info->bufferram = memcg_page_state(memcg, NR_FILE_PAGES);
 		info->sharedram = memcg_page_state(memcg, NR_SHMEM);
 		mem_cgroup_put(memcg);

@@ -3027,7 +3027,7 @@ static int fake_swap_show(struct seq_file *swap, void *v)
 	unsigned long totalram = (u64)READ_ONCE(memcg->memory.max);
 	unsigned long memusage = page_counter_read(&memcg->memory);
 	unsigned long proactive_usedswap;
-	unsigned long totalswap, usedswap;
+	unsigned long totalswap, usedswap, normal_usedswap;
 	struct sysinfo i;

 	si_swapinfo(&i);
@@ -3063,20 +3063,31 @@ static int fake_swap_show(struct seq_file *swap, void *v)
 		}
 	}

-	if (!totalswap && proactive_usedswap) {
-		totalswap = proactive_usedswap;
-		usedswap = proactive_usedswap;
-	}
+	normal_usedswap = (usedswap > proactive_usedswap) ?
+		(usedswap - proactive_usedswap) : 0;
+	if (normal_usedswap > totalswap)
+		normal_usedswap = totalswap;

-	if (!totalswap)
+	if (!totalswap && !proactive_usedswap)
 		return 0;

-	seq_printf(swap, "%-40s%s\t%lu\t%s%lu\t%s%d\n",
-			"virtual",
-			"virtual\t",
-			totalswap, totalswap < 10000000 ? "\t" : "",
-			usedswap, usedswap < 10000000 ? "\t" : "",
-			-1);
+	if (totalswap) {
+		seq_printf(swap, "%-40s%s\t%lu\t%s%lu\t%s%d\n",
+				"virtual",
+				"virtual\t",
+				totalswap, totalswap < 10000000 ? "\t" : "",
+				normal_usedswap, normal_usedswap < 10000000 ? "\t" : "",
+				-1);
+	}
+
+	if (proactive_usedswap) {
+		seq_printf(swap, "%-40s%s\t%lu\t%s%lu\t%s%d\n",
+				"virtual-system",
+				"virtual\t",
+				proactive_usedswap, proactive_usedswap < 10000000 ? "\t" : "",
+				proactive_usedswap, proactive_usedswap < 10000000 ? "\t" : "",
+				-2);
+	}
 	return 0;
 }
